    @Override
    @Transactional
    public Void deleteTopic(Long topicId) {
        try {
            log.info("Deleting topic with ID: {}", topicId);

            Topic topic = topicRepository.findById(topicId)
                    .orElseThrow(() -> new RuntimeException("Topic not found with ID: " + topicId));

