    }

    // Helper methods
    private TopicResponseDto buildTopicResponseDto(Topic topic) {
        return TopicResponseDto.builder()
                .id(topic.getId())
                .name(topic.getName())
                .description(null) // No description field in entity
                .problemCount(0) // Cannot get count without relationship
                .createdAt(topic.getCreatedAt())
                .build();
    }

    private TopicWithStatsResponseDto buildTopicWithStatsResponseDto(Topic topic) {
        // Cannot get problem statistics without relationship
        return TopicWithStatsResponseDto.builder()
                .id(topic.getId())
                .name(topic.getName())
                .description(null)
                .totalProblems(0)
                .easyProblems(0)
                .mediumProblems(0)
                .hardProblems(0)
                .acceptanceRate(0)
                .createdAt(topic.getCreatedAt())
                .build();
    }
}
